CREATE TABLE ai_agent_definition(id BIGINT AUTO_INCREMENT PRIMARY KEY,agent_key VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,gateway_url VARCHAR(500) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',configuration JSON NOT NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6));
CREATE TABLE ai_runtime_run(id BIGINT AUTO_INCREMENT PRIMARY KEY,run_key CHAR(36) NOT NULL UNIQUE,user_id BIGINT NOT NULL,runtime_type VARCHAR(30) NOT NULL,goal MEDIUMTEXT NOT NULL,status VARCHAR(30) NOT NULL,agent_key VARCHAR(80),request_payload JSON,response_payload JSON,error_code VARCHAR(80),created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),INDEX idx_runtime_run_user(user_id,created_at));
CREATE TABLE ai_browser_extension_session(id BIGINT AUTO_INCREMENT PRIMARY KEY,session_key CHAR(36) NOT NULL UNIQUE,user_id BIGINT NOT NULL,extension_version VARCHAR(40) NOT NULL,chrome_version VARCHAR(80),status VARCHAR(20) NOT NULL,capabilities JSON NOT NULL,last_seen_at TIMESTAMP(6) NOT NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_extension_user(user_id,last_seen_at));
CREATE TABLE ai_web_agent_participant(id BIGINT AUTO_INCREMENT PRIMARY KEY,run_id BIGINT NOT NULL,provider_key VARCHAR(40) NOT NULL,role_key VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,result_text MEDIUMTEXT,error_code VARCHAR(80),started_at TIMESTAMP(6),completed_at TIMESTAMP(6),UNIQUE KEY uk_web_participant(run_id,provider_key,role_key),FOREIGN KEY(run_id) REFERENCES ai_runtime_run(id));
INSERT INTO ai_agent_definition(agent_key,name,gateway_url,status,configuration) VALUES('default-external-agent','External Agent Runtime','http://127.0.0.1:8642','ACTIVE',JSON_OBJECT('protocolVersion','1.0','frameworkAgnostic',true));
